import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CKa26rr5.js";const u=JSON.parse('{"title":"Poulpy in 3D","description":"","frontmatter":{},"headers":[],"relativePath":"docs/poulpy-3d.md","filePath":"docs/poulpy-3d.md"}'),n={name:"docs/poulpy-3d.md"};function i(h,e,r,d,l,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="poulpy-in-3d" tabindex="-1">Poulpy in 3D <a class="header-anchor" href="#poulpy-in-3d" aria-label="Permalink to &quot;Poulpy in 3D&quot;">​</a></h1><p>The plush as a solid you can turn around: a bubble of a head tucked into eight puffy arms, drawn with flat cartoon shading. One file, <a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/model.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/model.mjs</code></a>, describes his shape; the <a href="https://tkint.github.io/coach-poulpy/storybook/?path=/docs/brand-poulpy-in-3d--docs" target="_blank" rel="noreferrer">Poulpy in 3D</a> page of the component workshop draws it live, with a page for each of <a href="#his-moves">his moves</a>, and <a href="https://github.com/tkint/coach-poulpy/blob/main/design/build-poulpy-3d.mjs" target="_blank" rel="noreferrer"><code>design/build-poulpy-3d.mjs</code></a> writes it as glTF files. He is not in the apps yet: this is the reference to build from.</p><h2 id="the-rules-of-the-shape" tabindex="-1">The rules of the shape <a class="header-anchor" href="#the-rules-of-the-shape" aria-label="Permalink to &quot;The rules of the shape&quot;">​</a></h2><p>These were settled with the owner on the first model; the reasons are in <a href="./brand-decisions#14-poulpy-in-3d-a-bubble-plush-in-flat-shading">Brand decisions</a>.</p><ul><li><strong>Chibi, never realistic.</strong> A big round head, big eyes, short arms. The face is the 2D drawing&#39;s, pressed onto the head, so every <a href="https://tkint.github.io/coach-poulpy/storybook/?path=/docs/brand-drawings--docs" target="_blank" rel="noreferrer">drawing</a> and the model show the same Poulpy.</li><li><strong>The head is tucked in.</strong> It sinks into the arms, which wrap around its base, instead of resting on top of them.</li><li><strong>Eight arms, always down.</strong> They lie on the floor as on the plush; a mood shows on his face and in his colour, never by lifting an arm. When he <a href="#little-jumps">jumps</a> they hang under him.</li><li><strong>The other side is underneath.</strong> Each arm is one smooth shape, the side&#39;s colour on top and the other side&#39;s colour below a low line, with no ridge or shelf between them. The base of the head is cut at the same height, so the whole underside is one colour: ember under the blue side, blue under the ember side.</li><li><strong>Flat, like a drawing.</strong> Plain token colours, one soft shadow band and one faint gleam. No gloss, no reflections, no fabric texture.</li><li><strong>The light belongs to the room.</strong> It comes from the viewer&#39;s upper left and stays there: the shade and the gleam slide over Poulpy as he turns, they are never painted on him.</li><li><strong>The outline is optional and off by default.</strong> It is there for small sizes or busy backgrounds.</li></ul><h2 id="his-six-moods" tabindex="-1">His six moods <a class="header-anchor" href="#his-six-moods" aria-label="Permalink to &quot;His six moods&quot;">​</a></h2><p>The model makes the six <a href="./brand#moods">moods</a> of the drawings: the same faces, pressed onto the head feature by feature, and the same shades, from the <code>mood</code> tokens. The side of the plush follows the mood, so the three ember moods show blue underneath.</p><ul><li><strong>The faces are the drawings&#39;.</strong> Each face in <code>model.mjs</code> is written in the 2D drawing&#39;s own coordinates, so the two can be read side by side and a change to one is copied to the other.</li><li><strong>A mood changes his face and his shade, never his shape.</strong> Heavy lids, brows, a smirk or clenched teeth lie on the head like the eyes do; his arms stay down.</li></ul><h2 id="his-twelve-poses" tabindex="-1">His twelve poses <a class="header-anchor" href="#his-twelve-poses" aria-label="Permalink to &quot;His twelve poses&quot;">​</a></h2><p>The model also takes the twelve <a href="./brand#when-each-drawing-shows">poses</a> of the drawings, each in the shade of its mood. They are in <a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poses.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/poses.mjs</code></a>, built on the shape and the faces of <code>model.mjs</code>.</p><ul><li><strong>What he wears is solid.</strong> The sweatband goes all the way around his head, the nightcap sits on it, the medal rests on his front arm and the dumbbell lies on the floor beside him: turn him and they turn with him.</li><li><strong>What is on him is on his skin.</strong> The plasters and the vein are laid against his head where the drawing has them and wrapped around it; sweat and tears are part of his face. Turn him and they stay where they are.</li><li><strong>The comic effects stay flat and face the viewer.</strong> Sparks, confetti, puffs, bubbles and lettering are the drawing&#39;s own, standing in front of him or behind him, and they keep facing whoever looks while he turns.</li><li><strong>Cocky has no halo and no &quot;PR!&quot; badge in 3D.</strong> The owner dropped them; his sparks stay, and become solid stars when he <a href="#the-cocky-one-winks">winks</a>.</li><li><strong>He still never lifts an arm.</strong> Standing tall stretches his arms taller and lifts his head with them; Side glance leans his head. Nothing else moves.</li><li><strong>The loader is his outline from above.</strong> He is seen from straight overhead and only the edge of his shape is drawn, in the brand blue and see-through, as the old loader was: the flower of his eight loose tentacles round his head, with no line inside, and a line bold enough for the bases of neighbouring tentacles to touch. He swings half a turn one way and then half a turn the other way (from -180° to 180°), forever, once every 3.6 s (once every 12 s with reduced motion), easing at each end. The swing is <code>LoaderSwing</code> in the shared Kotlin, and <code>PoulpyLoader</code> on Android and iOS, <code>MobilePoulpyLoader</code> and <code>CpPoulpyLoader</code> in the workshop all follow it. He is fitted inside the circle he turns in, so he never leaves his frame.</li></ul><h2 id="his-pictures" tabindex="-1">His pictures <a class="header-anchor" href="#his-pictures" aria-label="Permalink to &quot;His pictures&quot;">​</a></h2><p>Where the apps and the website do not need him live, they take a picture of him: one for each of the six moods and twelve poses, painted from the model, and one more for the loader. They are in <a href="https://github.com/tkint/coach-poulpy/tree/main/design/poulpy-3d/pictures" target="_blank" rel="noreferrer"><code>design/poulpy-3d/pictures</code></a>, one PNG each at 744 by 678 pixels, the same frame as the drawings they replace so a picture can take a drawing&#39;s place without moving anything. <strong>They are transparent around him</strong>, with no background and no tile, so they sit on a light or a dark screen alike; the preview below shows them on the page&#39;s own background.</p><ul><li><strong>They are painted by our own script.</strong> <a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/picture.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/picture.mjs</code></a> draws what <code>model.mjs</code> and <code>poses.mjs</code> build, pixel by pixel, in plain JavaScript with the look of <code>LOOK</code>: the same flat shading, gleam and floor shadow as the live view. No browser or graphics card is involved, so every machine writes the same pixels, as for the app icons.</li><li><strong>Every picture is taken from the same place.</strong> He is seen from a little above and face on, close enough to fill the frame, and the same distance for all of them so he is the same size from one to the next.</li><li><strong>The floor shadow is part of the picture</strong>: a see-through dark blue that fades to nothing, so it shows on a light screen and disappears on a dark one.</li><li><strong>Generated, never edited.</strong> <code>node design/build-poulpy-pictures.mjs</code> writes them and CI runs it with <code>--check</code>. Change the model, a face or a pose, then regenerate.</li></ul><h2 id="his-moves" tabindex="-1">His moves <a class="header-anchor" href="#his-moves" aria-label="Permalink to &quot;His moves&quot;">​</a></h2><p>He moves in 3D too. Each move has its own page in the component workshop, so only one runs at a time:</p><ul><li><a href="#turning-in-short-steps">Turning in short steps</a>: his idle.</li><li><a href="#little-jumps">Little jumps</a> on the spot.</li><li><a href="#jumping-around">Jumping around</a>: the same jumps, each turning him.</li><li><a href="#the-champion-jumps-for-joy">The champion jumps for joy</a>, his medal bouncing and confetti flying.</li><li><a href="#the-cocky-one-winks">The cocky one winks</a>, and stars pop up around him.</li></ul><p>All of them are one file, <a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/motion.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/motion.mjs</code></a>, next to the shape. A preview only moves while it is on screen, and starts paused for anyone who asked their device for less motion; an app must do the same.</p><h2 id="turning-in-short-steps" tabindex="-1">Turning in short steps <a class="header-anchor" href="#turning-in-short-steps" aria-label="Permalink to &quot;Turning in short steps&quot;">​</a></h2><p>His idle move: Poulpy likes to turn around on the spot, a short step of 20 to 30 degrees at a time, stopping after each one. Fifteen steps bring him all the way around, in about 17 seconds, and then he goes again.</p><p>His arms are not stiff. Each one bends at three places, and every bend is a small spring: when he steps the arms trail behind, when he stops they swing a little past him and settle, the tips last. The controls of the turning model are there to try other feels, and each shows its value so a setting can be quoted and written into the design. <strong>Step</strong> sets how far he turns each time, from 1 to 180 degrees, keeping the small differences between one step and the next; 24 is the design. <strong>Soft arms</strong> loosens or stiffens those springs: 1 is the design, 0 is the stiff plush with no springs at all and 4 is very floppy. <strong>Speed</strong> plays the whole move faster or slower, 1 being the design. The two arrows pick the direction, seen from above; the design turns anticlockwise, to his left.</p><ul><li><strong>The arms slide, they never lift.</strong> Every bend turns flat on the floor, so the move keeps the plush&#39;s shape as the <a href="./brand#character-rules">brand rules</a> ask.</li><li><strong>He winds up, then goes.</strong> A small lean back before each step, a quick turn, and a slight rock past the mark as he stops.</li><li><strong>The head dips as he turns</strong> and bounces back, by a few hundredths of its height, widening to keep its volume. His face rides along with it.</li><li><strong>No two steps or arms are quite alike.</strong> The steps vary between 20 and 30 degrees and the pauses between 0.45 and 0.75 seconds, and each arm&#39;s springs are a little stiffer or softer than its neighbours&#39;, so the arms fall out of step with each other.</li><li><strong>Reduced motion keeps him still.</strong> The preview starts paused for anyone who asked their device for less motion, and an app must do the same.</li></ul><p><code>TURN</code> at the top of <code>motion.mjs</code> holds every number: the steps and pauses, the wind-up, how eager and how bouncy his body is, how soft each length of arm is, how much the floor holds the arms back and how far the head dips. <code>createTurn()</code> runs it live, as the workshop&#39;s page does, and <code>bakeTurn()</code> writes it down frame by frame for the glTF files.</p><h2 id="little-jumps" tabindex="-1">Little jumps <a class="header-anchor" href="#little-jumps" aria-label="Permalink to &quot;Little jumps&quot;">​</a></h2><p>Poulpy can also jump on the spot. He tucks his head down into his arms, which widen flat on the floor, then he goes up. His arms are part of him: their base goes up with his head and their tips hang a little lower, the last to leave the floor. In the air he tilts to one side, the other side at the next jump, and as he lands his head goes a little down into his arms before he stands again.</p><p><strong>The jump is a preview, still being tuned.</strong> It runs live here and is not in the glTF files yet: its values are written into them once the owner has settled them on this page. Every control shows its value so a setting can be quoted. Heights are in the model&#39;s units, where his head is about 1 from centre to edge.</p><table tabindex="0"><thead><tr><th>Control</th><th>What it sets</th><th>Design</th></tr></thead><tbody><tr><td><strong>Height</strong></td><td>How far he goes up</td><td>0.34</td></tr><tr><td><strong>Tuck</strong></td><td>How far his head goes down into his arms before the jump</td><td>0.16</td></tr><tr><td><strong>Landing</strong></td><td>How far his head goes down into his arms as he lands</td><td>0.10</td></tr><tr><td><strong>Spread</strong></td><td>How far his arms slide outwards when his head is tucked all the way in</td><td>0.14</td></tr><tr><td><strong>Hang</strong></td><td>How heavy his arms are, so how low their tips hang in the air</td><td>1</td></tr><tr><td><strong>Lean</strong></td><td>How far he tilts to the side in the air, in degrees</td><td>7</td></tr><tr><td><strong>Pause</strong></td><td>Seconds he stands between two jumps, on average</td><td>0.55</td></tr><tr><td><strong>Soft arms</strong></td><td>How loosely his arms hang and trail, as for the turn</td><td>1</td></tr><tr><td><strong>Speed</strong></td><td>Plays the whole move faster or slower</td><td>1</td></tr></tbody></table><ul><li><strong>His head never leaves his arms.</strong> It goes down into them, to tuck and to land, and never up out of them: when he goes up they go with him.</li><li><strong>His arms widen as his head comes down.</strong> They stay flat on the floor and slide outwards, as a plush does when it is pressed.</li><li><strong>The arms hang, he never raises them.</strong> Up and down, each arm bends at the same three places as when he turns. A spring holds each length level with the one before it, its weight pulls it down and the floor stops it: the tips leave the floor last, hang under him in the air and touch down first. A length may hang nearly straight down when it has to. On the side he tilts to, the arms lie flat against the floor.</li><li><strong>His head squashes and stretches.</strong> It widens as it tucks in and as he lands, and thins a little while it moves fast, keeping its volume.</li><li><strong>Reduced motion keeps him still</strong>, as for the turn.</li></ul><p><code>JUMP</code> in <code>motion.mjs</code> holds the jump&#39;s numbers, next to <code>TURN</code>, and <code>createJump()</code> runs it live.</p><h2 id="jumping-around" tabindex="-1">Jumping around <a class="header-anchor" href="#jumping-around" aria-label="Permalink to &quot;Jumping around&quot;">​</a></h2><p>The same <a href="#little-jumps">jump</a> can turn him: each jump takes him one step around, the steps being those of his turn. He winds up while he tucks, turns in the air and his arms trail behind as they do on the floor.</p><p><strong>Step</strong> and the two arrows work as for the turn, and here Step goes up to 720 degrees: at 360 a jump is a whole turn, at 720 two. The steps keep their small differences, so he does not land facing quite the same way each time. Every other control is the jump&#39;s.</p><p>Given a <code>stride</code>, <code>createJump()</code> turns him as <code>createTurn()</code> does.</p><h2 id="the-champion-jumps-for-joy" tabindex="-1">The champion jumps for joy <a class="header-anchor" href="#the-champion-jumps-for-joy" aria-label="Permalink to &quot;The champion jumps for joy&quot;">​</a></h2><p>The Champion pose, moving: he cannot hold still. His jumps are the <a href="#little-jumps">little jumps</a>, higher, leaning more and closer together, and two things answer them.</p><ul><li><strong>His medal has its own weight.</strong> It hangs on its ribbon from under his head and rests on his front arm. When he drops it floats up off him, then falls back on his arm with a small bounce; when he tilts it slides to that side and wobbles back. Nothing is drawn by hand: it is a weight on a hinge, pulled down and stopped by his arm.</li><li><strong>Confetti flies at each jump.</strong> A burst leaves the floor around him as he does, goes up past his head and flutters down, tumbling. It lands flat and stays on the floor until it flies again, so the floor fills up as he goes on. The pieces are solid here and belong to the room: turn the view and they stay where they are. The still pose keeps its flat confetti.</li><li><strong>Every run is the same.</strong> Where each piece starts and how it tumbles comes from a fixed list, not from chance, so the move can be written into a file later.</li><li><strong>He still never lifts an arm.</strong> His joy is in the jump, his face, the medal and the confetti.</li></ul><p>The controls are the jump&#39;s, starting from the champion&#39;s own values: Height 0.50, Lean 9 and Pause 0.26. <code>CHEER</code> in <code>motion.mjs</code> holds those, the medal&#39;s weight, bounce and reach and the confetti&#39;s numbers, and <code>createCheer()</code> runs it live. Like the jump it is a preview, not in the glTF files yet.</p><h2 id="the-cocky-one-winks" tabindex="-1">The cocky one winks <a class="header-anchor" href="#the-cocky-one-winks" aria-label="Permalink to &quot;The cocky one winks&quot;">​</a></h2><p>The Cocky pose, moving. He looks at you with both eyes wide open, then shuts one eye (his right, unless told otherwise), lifts the other brow and his mouth slides into the cocky smirk. He holds it, opens his eye and starts again.</p><ul><li><strong>His face moves, feature by feature.</strong> The eye narrows to a line and the line bends into the wink; the brow and the mouth go from plain to cocky with it. <code>winkFace()</code> in <code>poses.mjs</code> gives his face at any point between the two, in the drawing&#39;s coordinates like every face.</li><li><strong>His head goes with it.</strong> It leans a little to the side of the eye he shuts and dips, on a spring, then comes back.</li><li><strong>The stars come with the wink.</strong> There are none while his eyes are open. As the eye shuts they pop up one after the other, each a little past its size and back, and they leave when he opens it.</li><li><strong>The stars are solid and they twinkle.</strong> Each is a four-point star cut like a gem, in the room around him where the drawing has its sparks. It grows and shrinks, turns on itself and rocks, and no two keep the same time. Turn the view and they stay where they are.</li><li><strong>No halo, no badge.</strong> The drawing&#39;s glow and its &quot;PR!&quot; are not part of him in 3D.</li></ul><p>The switch picks the eye he shuts, named for him: his right eye, the design, is on your left. His brow, his smirk and the lean of his head go to the other side with it.</p><p><code>WINK</code> in <code>motion.mjs</code> holds the timing, the lean of his head and the stars&#39; numbers, and <code>createWink()</code> runs it live. It is a preview, not in the glTF files yet.</p><h2 id="using-the-model" tabindex="-1">Using the model <a class="header-anchor" href="#using-the-model" aria-label="Permalink to &quot;Using the model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poulpy_blue.glb" target="_blank" rel="noreferrer">poulpy_blue.glb</a></td><td>The blue, smiling side, as binary glTF</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poulpy_ember.glb" target="_blank" rel="noreferrer">poulpy_ember.glb</a></td><td>The ember, grumpy side, as binary glTF</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poulpy_blue_turn.glb" target="_blank" rel="noreferrer">poulpy_blue_turn.glb</a></td><td>The blue side with the animation <code>turn</code>: one full turn in short steps, made to loop</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poulpy_ember_turn.glb" target="_blank" rel="noreferrer">poulpy_ember_turn.glb</a></td><td>The ember side with the same animation</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/model.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/model.mjs</code></a></td><td>The shape itself, as plain JavaScript with no dependency</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/poses.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/poses.mjs</code></a></td><td>His twelve poses, the same way</td></tr><tr><td><a href="https://github.com/tkint/coach-poulpy/blob/main/design/poulpy-3d/motion.mjs" target="_blank" rel="noreferrer"><code>design/poulpy-3d/motion.mjs</code></a></td><td>How he moves, the same way</td></tr></tbody></table><p>The glTF files open in any 3D tool or engine. Poulpy stands on the floor (y = 0, y up) and faces +z; his head is about one unit from centre to edge. In the two files that stand still, each part is its own named mesh (<code>head</code>, <code>head_lining</code>, <code>arm_1</code> to <code>arm_8</code> and their <code>_lining</code>, <code>eye_left</code>, <code>eye_left_shine</code>, <code>cheek_left</code>, <code>mouth</code>, <code>gleam</code>, plus <code>brow_left</code> and <code>brow_right</code> on the ember side; left and right are Poulpy&#39;s own), so a part can be recoloured, hidden or animated on its own.</p><p>The two <code>_turn</code> files hold the same meshes, rigged. The node <code>turn</code> faces him and <code>squash</code> under it carries his head and face; each arm is skinned to <code>turn</code> and to its own chain of three joints, <code>arm_1_bend_1</code> to <code>arm_1_bend_3</code> from the head outwards. The animation <code>turn</code> plays one full turn at 30 frames a second and ends where it starts, so any player can loop it. It is a recording of the springs at their design values: an engine that wants them live, to change the softness or to react to something, runs <code>createTurn()</code> from <code>motion.mjs</code> on the same joints, as the workshop&#39;s preview does.</p><p>A glTF file only carries shapes and plain matte colours. The look is the renderer&#39;s job, and <code>LOOK</code> in <code>model.mjs</code> gives its numbers: the light&#39;s direction as the viewer sees it, the shadow band&#39;s strength, where the gleam sits, and the outline&#39;s width and tint. A renderer that wants the gleam to follow the light drops the <code>gleam</code> mesh from the file and asks <code>gleamPatch(direction)</code> for a new one whenever Poulpy or the camera turns. <a href="https://github.com/tkint/coach-poulpy/blob/main/web/storybook/stories/brand/poulpy3dScene.ts" target="_blank" rel="noreferrer"><code>poulpy3dScene.ts</code></a>, which draws the workshop&#39;s preview with three.js, is the worked example.</p><h2 id="changing-the-design" tabindex="-1">Changing the design <a class="header-anchor" href="#changing-the-design" aria-label="Permalink to &quot;Changing the design&quot;">​</a></h2><p>Everything that defines him is at the top of <code>model.mjs</code>, in three plainly named objects:</p><ul><li><code>SHAPE</code>: the size of the head and how deep it sits, the number, size and reach of the arms, the height of the line between the two colours, and where the face sits.</li><li><code>FACES</code>: the eyes, lids, brows, mouth and cheeks of each face, feature by feature, in the coordinates of the 2D drawings of <code>design/build-poulpy.mjs</code>.</li><li><code>MOODS</code>: for each of his six moods, the side of the plush and the face he makes. <code>buildPoulpy3d({ mood, tone })</code> builds him in one, tinted with that mood&#39;s <code>mood</code> token.</li><li><code>LOOK</code>: the light, the shadow band, the gleam and the outline.</li></ul><p>His poses are in <code>poses.mjs</code>: <code>POSES</code> gives each one its mood, its face, what he wears, what lies on his head and the effects around him, all in the drawing&#39;s coordinates, and <code>buildPoulpyPose({ pose })</code> builds it.</p><p>How he moves is in <code>motion.mjs</code>: <code>TURN</code> for his turn, <code>JUMP</code> for his jump, <code>CHEER</code> for the champion&#39;s, <code>WINK</code> for the cocky one&#39;s and <code>RIG</code> for where the arms bend.</p><p>His colours are the <code>color.poulpy</code> tokens of <a href="https://github.com/tkint/coach-poulpy/blob/main/design/tokens.json" target="_blank" rel="noreferrer"><code>design/tokens.json</code></a>, never written into the model.</p><p>Edit, then regenerate and look at the workshop&#39;s page (<code>npm run storybook</code> in <code>web/</code>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy-3d.mjs</span></span></code></pre></div><p>CI runs it with <code>--check</code> and fails when the committed glTF files no longer match <code>model.mjs</code> and <code>motion.mjs</code>. A new mood in 3D starts as a new entry in <code>FACES</code> and <code>MOODS</code>, a new pose as a new entry in <code>POSES</code>; a new move starts next to <code>TURN</code>, <code>JUMP</code>, <code>CHEER</code> and <code>WINK</code> in <code>motion.mjs</code>, with a page of its own in the workshop. Both follow the <a href="./brand#character-rules">brand rules</a> like any drawing.</p>',56)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
